look.customCSS:
/* ───── 黄油吐司 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/90px 90px,#FBF6EC !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一整块烤得刚好的吐司色，底边一道焦黄面包边 */
[data-wk="chathead"]{background:linear-gradient(180deg,#F8E4BF,#F1D19C) !important;border-bottom:4px solid #B87A45 !important;box-shadow:0 3px 0 #9A6236,0 6px 12px rgba(154,98,54,.15) !important}
[data-wk="headink"],[data-wk="headink"] *{color:#5A3E2B !important;font-weight:600 !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#9C7B5C !important}
[data-wk="chatback"] svg{stroke:#5A3E2B !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important;flex-shrink:0 !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;position:relative !important;overflow:visible !important;margin-left:-6px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:30px !important;height:30px !important;min-width:30px !important;flex-shrink:0 !important;aspect-ratio:1 !important;border-radius:50% !important;box-shadow:0 0 0 2.5px #F5C142,0 0 0 6px #fff,3px 2px 0 6px #fff,-3px 3px 0 6px #fff !important}
[data-wk="chathead"] [data-wk="headme"]::before{content:"" !important;position:absolute !important;left:-12px !important;bottom:-4px !important;width:15px !important;height:12px !important;z-index:3 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offline"] [data-wk="chathead"] [data-wk="headme"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:84px !important;margin-left:6px !important}
[data-wk="chathead"] [data-wk="headname"] > div:last-child{white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}

/* 头像：荷包蛋——头像是蛋黄，外面一圈蛋白软软地摊开 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]),[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] > :first-child[data-wk="avatar"],[data-wk="rpsingle"] > [data-wk="rpcard"] + [data-wk="avatar"]{box-shadow:0 0 0 3px #F5C142,0 0 0 9px #fff,5px 3px 0 10px #fff,-6px 4px 0 9px #fff,3px -6px 0 9px #fff,-4px -4px 0 10px #fff,0 6px 14px 8px rgba(184,122,69,.18) !important}
[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{margin:6px 4px !important}

/* 气泡：一片吐司——上头宽出一圈面包帽、焦黄面包边；我的是烤成金黄的那片，右边一块黄油 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;isolation:isolate !important;line-height:1.6 !important;margin-top:12px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FFF8EA !important;color:#5A3E2B !important;border:3px solid #B87A45 !important;border-top:none !important;border-radius:0 0 12px 12px !important;padding:12px 16px 10px !important;box-shadow:0 4px 8px rgba(154,98,54,.12) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;left:-6px !important;right:-6px !important;top:-12px !important;height:22px !important;background:#FFF8EA !important;border:3px solid #B87A45 !important;border-radius:50% 50% 10px 10px / 70% 70% 10px 10px !important;z-index:-1 !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:url("data:image/svg+xml;base64,") right 9px center/24px 20px no-repeat,linear-gradient(180deg,#E9A95E,#D98F45) !important;color:#fff !important;border:3px solid #9A6236 !important;border-top:none !important;border-radius:0 0 12px 12px !important;padding:12px 40px 10px 16px !important;box-shadow:0 4px 8px rgba(154,98,54,.2) !important;text-shadow:0 1px 0 rgba(154,98,54,.4) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;left:-6px !important;right:-6px !important;top:-12px !important;height:22px !important;background:#E9A95E !important;border:3px solid #9A6236 !important;border-radius:50% 50% 10px 10px / 70% 70% 10px 10px !important;z-index:-1 !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:5px !important;height:6px !important;z-index:-1 !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::after{background:#FFF8EA !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{background:#E9A95E !important}

/* 时间：两边一根麦穗 */
[data-wk="time"] > span{background:none !important;border:none !important;box-shadow:none !important;color:#B5A28E !important;font-size:11.5px !important;letter-spacing:.15em !important;display:inline-flex !important;align-items:center !important;gap:8px !important}
[data-wk="time"] > span::before,[data-wk="time"] > span::after{content:"" !important;width:34px !important;height:12px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="time"] > span::before{transform:scaleX(-1) !important}
/* 已读：一小块黄油；没读：一粒面包屑 */
[data-wk="meta"]{color:#B5A28E !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::before{content:"" !important;width:9px !important;height:7px !important;border-radius:2.5px !important;background:#F7D35E !important;box-shadow:0 0 0 1px #E3B83A !important}
[data-wk="meta"][data-read="0"]::before{width:6px !important;height:6px !important;border-radius:50% !important;background:transparent !important;box-shadow:0 0 0 1.2px #B5A28E !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#B5A28E !important;padding:2px 0 0 66px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 66px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFF8EA !important;border:3px solid #B87A45 !important;border-radius:12px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#B87A45 !important}

/* 动描：一张油纸（不是吐司），前面一根麦穗；我写的动作是果酱粉，靠右 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{display:inline-block !important;position:relative !important;background:#F3ECDD !important;border:none !important;border-radius:4px !important;box-shadow:0 1px 0 #EBDCC6 !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;color:#8F7660 !important;opacity:1 !important;font-style:italic !important;font-size:12.5px !important;line-height:1.75 !important;padding:5px 14px 5px 34px !important}
[data-wk="narrink"]::before,[data-wk="myactink"]::before{content:"" !important;position:absolute !important;left:8px !important;top:9px !important;width:22px !important;height:9px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="myactink"]{background:#FBE3E1 !important;color:#B2595C !important;padding:5px 14px 5px 14px !important}
[data-wk="myactink"]::before{content:none !important}
/* 系统提示 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#B5A28E !important;font-size:11px !important;font-style:normal !important;letter-spacing:.08em !important}
[data-wk="sysnotetext"]::before{content:"∙ " !important;color:#B87A45 !important}
[data-wk="sysnotetext"]::after{content:" ∙" !important;color:#B87A45 !important}
[data-wk="narrbar"]{background:#FFF8EA !important;border-top:1px solid #EBDCC6 !important}
[data-wk="narrkind"]{border:1px solid #EBDCC6 !important;border-radius:999px !important;background:transparent !important;color:#B5A28E !important}
[data-wk="narrkind"][data-on="1"]{background:#B87A45 !important;border-color:#B87A45 !important;color:#fff !important}

/* 底栏：一块面包板，顶上一道面包边；左麦穗加号、白吐司色输入框、右黄油刀发送、果酱吐司回复 */
[data-wk="composer"]{background:#FFF8EA !important;border-top:4px solid #B87A45 !important;box-shadow:0 -3px 0 #F1D19C !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:#fff !important;border:1.5px solid #EBDCC6 !important;border-radius:12px !important;color:#5A3E2B !important}
[data-wk="chatinput"]::placeholder{color:#CDBBA6 !important}
[data-wk="chatplus"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] svg{display:none !important}
[data-wk="send"]{width:40px !important;min-width:40px !important;height:36px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:38px !important;min-width:38px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}

/* 打电话那一屏（语音）：烤面包的暖黄；按键是一片片吐司，挂断是一罐果酱红 */
[data-wk="call"][data-video="0"]{background:radial-gradient(ellipse at 50% 22%,rgba(255,248,234,.55),transparent 60%),linear-gradient(180deg,#F1C88A,#D98F45 70%,#B8743F) !important}
[data-wk="call"][data-video="0"] > button:first-child{background:rgba(255,255,255,.25) !important}
[data-wk="calltitle"]{color:#fff !important;font-weight:600 !important;text-shadow:0 1px 0 rgba(154,98,54,.4) !important}
[data-wk="callavatar"]{border-radius:50% !important;box-shadow:0 0 0 6px #F5C142,0 0 0 20px #fff,12px 8px 0 20px #fff,-14px 10px 0 18px #fff,8px -14px 0 18px #fff,0 18px 30px 16px rgba(154,98,54,.3) !important}
[data-wk="callbtns"] button > span:first-child{background:#FFF3DC !important;border-radius:45% 45% 14px 14px / 40% 40% 14px 14px !important;box-shadow:0 0 0 3px #B87A45,0 5px 0 3px #9A6236,0 10px 18px rgba(0,0,0,.2) !important}
[data-wk="callbtns"] button > span:first-child svg{stroke:#9A6236 !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child{background:#D9575B !important;border-radius:50% !important;box-shadow:0 0 0 3px #fff,0 5px 0 3px #B23F44,0 10px 18px rgba(0,0,0,.2) !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child svg{stroke:#fff !important}
[data-wk="callbubble"]{background:#FFF8EA !important;color:#5A3E2B !important;border:2px solid #B87A45 !important;border-radius:12px !important}
[data-wk="callmsg"][data-me="1"] [data-wk="callbubble"]{background:#E9A95E !important;color:#fff !important;border-color:#9A6236 !important}
[data-wk="callbubble"]::before,[data-wk="callbubble"]::after{content:none !important}
[data-wk="note"][data-part="callsum"]{display:block !important;margin:6px auto 0 !important;background:#FFF8EA !important;border:2px solid #B87A45 !important;border-radius:12px !important;padding:8px 14px !important;color:#8F7660 !important;font-size:12px !important;line-height:1.65 !important;text-align:left !important}
[data-wk="noteink"]{color:#B5A28E !important}
[data-wk="callact"]{color:#B87A45 !important}

/* ───── 黄油吐司 · 第二批：卡片（形状不动；都是一片厚吐司——奶油芯、焦黄面包边、顶上圆一点） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"],[data-wk="wxcard"]{position:relative !important;overflow:hidden !important;background:#FFF8EA !important;border:3px solid #B87A45 !important;border-radius:22px 22px 12px 12px / 18px 18px 12px 12px !important;box-shadow:0 4px 0 #9A6236,0 8px 14px rgba(154,98,54,.15) !important;color:#5A3E2B !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *,[data-wk="photocard"] *,[data-wk="wxcard"] *{color:#5A3E2B !important;border-color:#EBDCC6 !important}
/* 转账：金额烤焦黄色；收下盖一个荷包蛋 */
[data-wk="transferamount"],[data-wk="transfercur"]{color:#B87A45 !important}
[data-wk="transferrule"]{border:none !important;height:2px !important;background:#EBDCC6 !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:#FFF1D6 !important;border-top:2px solid #EBDCC6 !important}
[data-wk="transferbtn"]{border-radius:999px !important}
[data-wk="transferbtn"][data-part="take"]{background:#E9A95E !important;color:#fff !important;border:2px solid #9A6236 !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;border:2px solid #EBDCC6 !important}
[data-wk="transferseal"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;width:42px !important;height:42px !important;font-size:0 !important;color:transparent !important}
[data-wk="transferseal"] *{opacity:0 !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{transform:rotate(-12deg) !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.55 !important}
/* 红包：不是信封——一片抹满果酱的吐司，左边一罐果酱；领完果酱变淡 */
[data-wk="rpcard"]{position:relative !important;overflow:hidden !important;background:linear-gradient(180deg,#E8686B,#D9575B) !important;border:3px solid #B87A45 !important;border-radius:22px 22px 12px 12px / 18px 18px 12px 12px !important;box-shadow:0 4px 0 #9A6236,0 8px 14px rgba(154,98,54,.2) !important;padding-left:56px !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:12px !important;top:calc(50% - 17px) !important;width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important}
[data-wk="rpcard"] *{color:#fff !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{opacity:.65 !important}
[data-wk="rpenvelope"]{background:linear-gradient(180deg,#E8686B,#B23F44) !important;border:3px solid #B87A45 !important;border-radius:22px 22px 12px 12px / 18px 18px 12px 12px !important;box-shadow:0 6px 0 #9A6236,0 14px 30px rgba(0,0,0,.25) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:transparent !important;border:none !important}
[data-wk="rpenvelope"] *{color:#fff !important}
[data-wk="rpopenbtn"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;filter:drop-shadow(0 4px 6px rgba(0,0,0,.25)) !important}
[data-wk="rpopenbtn"] *{opacity:0 !important}
[data-wk="rpamount"]{color:#fff !important}
[data-wk="rpavatar"],[data-wk="rpavatar"] *{border-radius:50% !important}
[data-wk="rpavatar"]{box-shadow:0 0 0 3px #F5C142,0 0 0 7px #fff !important}
/* 照片：吐司框里一块浅奶黄小屏；语音：他白吐司、我金黄吐司 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:10px !important;background:#FFF1D6 !important;border:none !important;box-shadow:inset 0 0 0 2px #EBDCC6 !important}
[data-wk="photoface"] *,[data-wk="photohint"]{color:#9C7B5C !important}
[data-wk="photoface"] svg{stroke:#B87A45 !important}
[data-wk="voice"][data-me]{background:#FFF8EA !important;border:3px solid #B87A45 !important;border-radius:22px 22px 12px 12px / 18px 18px 12px 12px !important;box-shadow:0 3px 0 #9A6236 !important}
[data-wk="voice"][data-me="1"]{background:linear-gradient(180deg,#E9A95E,#D98F45) !important;border-color:#9A6236 !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#5A3E2B !important}
[data-wk="voice"][data-me="1"] > *{color:#fff !important}
[data-wk="voicewave"] span{background:#B87A45 !important}
[data-wk="voice"][data-me="1"] [data-wk="voicewave"] span{background:#fff !important}
/* 天气：太阳是一颗蛋黄；下面那句话垫奶黄 */
[data-wk="wxcardsky"]{background:transparent !important}
[data-wk="wxcardsky"] > div:first-child{background:radial-gradient(circle,#F5C142 0 10px,#fff 11px 17px,transparent 18px) !important}
[data-wk="wxcardsky"] svg{stroke:#B87A45 !important}
[data-wk="wxcardsky"] span[style*="999"],[data-wk="wxcardrain"]{background:#FFF1D6 !important;border:none !important}
[data-wk="wxcardsay"]{background:#FFF1D6 !important;border-top:2px solid #EBDCC6 !important}
[data-wk="wxcardsay"],[data-wk="wxcardsay"] *{color:#5A3E2B !important}
[data-wk="geopin"]{background:#D9575B !important;box-shadow:0 0 0 2px #fff !important}
[data-wk="geopinstem"]{background:#B87A45 !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 3px #F5C142,0 0 0 7px #fff !important}
/* 卡片下的已读：一小块黄油 */
[data-run][data-last="1"] + [data-wk="cardmeta"]::before{content:"" !important;display:inline-block !important;vertical-align:middle !important;width:9px !important;height:7px !important;border-radius:2.5px !important;background:#F7D35E !important;box-shadow:0 0 0 1px #E3B83A !important;margin:0 6px !important}
/* 拍一拍、通话结束 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;border:2px solid #EBDCC6 !important;background:#FFF8EA !important;border-radius:999px !important;padding:2px 14px !important;color:#B5A28E !important}
[data-wk="note"][data-part="call"] svg{stroke:#B5A28E !important}
/* 线下小结 */
[data-wk="offlogtitle"]{letter-spacing:.15em !important;color:#B87A45 !important;font-weight:600 !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#D9575B !important}
[data-wk="offlogtranscript"]{border-top:2px solid #EBDCC6 !important}
/* 加号面板：一片片小吐司 */
[data-wk="chatpanel"]{background:#FFF8EA !important;border-top:3px solid #B87A45 !important}
[data-wk="chattoolicon"]{background:#FFF8EA !important;border:3px solid #B87A45 !important;border-radius:22px 22px 12px 12px / 18px 18px 12px 12px !important;box-shadow:0 3px 0 #9A6236 !important}
[data-wk="chattool"]:nth-child(odd) [data-wk="chattoolicon"]{background:linear-gradient(180deg,#F6CB8E,#E9A95E) !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#9A6236 !important;color:#9A6236 !important}
[data-wk="chattoollabel"]{color:#9C7B5C !important}
/* 引用：左边一道面包边 */
[data-wk="quotedraft"]{background:#FFF8EA !important;border-top:2px solid #EBDCC6 !important}
[data-wk="quote"]{background:#FFF1D6 !important;color:#9C7B5C !important;border:none !important;border-left:4px solid #B87A45 !important;border-radius:6px !important;opacity:1 !important}
[data-wk="quoteicon"],[data-wk="quoteclear"]{color:#B87A45 !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid currentColor !important;padding-left:8px !important;opacity:.7 !important}
